#pragma once
#include "driver_backend.hpp"
struct Fine {
 CUdevice dev;CUcontext primary;double driver_init_ms=0,green_create_ms=0;std::vector<Group> groups;std::vector<CUdevResource> resources;
 Fine(){auto init_start=Clock::now();ck(cuInit(0),"init");ck(cuDeviceGet(&dev,0),"device");ck(cuDevicePrimaryCtxRetain(&primary,dev),"retain");ck(cuCtxSetCurrent(primary),"current");driver_init_ms=ms(init_start,Clock::now());auto green_start=Clock::now();CUdevResource all{},rem{};ck(cuDeviceGetDevResource(dev,&all,CU_DEV_RESOURCE_TYPE_SM),"resources");unsigned n=0;ck(cuDevSmResourceSplitByCount(nullptr,&n,&all,nullptr,0,2),"simulate split");if(n!=28)throw std::runtime_error("Expected 28 symmetric 2-SM resources");std::vector<CUdevResource>rs(n);ck(cuDevSmResourceSplitByCount(rs.data(),&n,&all,&rem,0,2),"split");resources=rs;for(auto&r:rs){Group g;CUdevResourceDesc d;ck(cuDevResourceGenerateDesc(&d,&r,1),"descriptor");ck(cuGreenCtxCreate(&g.green,d,dev,CU_GREEN_CTX_DEFAULT_STREAM),"green");ck(cuCtxFromGreenCtx(&g.ctx,g.green),"context");g.sms=r.sm.smCount;ck(cuCtxSetCurrent(g.ctx),"current");ck(cuGreenCtxStreamCreate(&g.stream,g.green,CU_STREAM_NON_BLOCKING,0),"stream");ck(cuEventCreate(&g.start,0),"event");ck(cuEventCreate(&g.end,0),"event");groups.push_back(g);}ck(cuCtxSetCurrent(primary),"current");green_create_ms=ms(green_start,Clock::now());}
 int merge(const std::vector<int>&ids){std::vector<CUdevResource>rs;for(int id:ids)rs.push_back(resources.at(id));Group g;CUdevResourceDesc d;ck(cuDevResourceGenerateDesc(&d,rs.data(),rs.size()),"merged descriptor");ck(cuGreenCtxCreate(&g.green,d,dev,CU_GREEN_CTX_DEFAULT_STREAM),"merged context");ck(cuCtxFromGreenCtx(&g.ctx,g.green),"merged convert");g.sms=ids.size()*2;ck(cuCtxSetCurrent(g.ctx),"merged current");ck(cuGreenCtxStreamCreate(&g.stream,g.green,CU_STREAM_NON_BLOCKING,0),"merged stream");ck(cuEventCreate(&g.start,0),"merged start");ck(cuEventCreate(&g.end,0),"merged end");groups.push_back(g);return groups.size()-1;}
 void current(int g){ck(cuCtxSetCurrent(groups.at(g).ctx),"current");}
 ~Fine(){for(auto&g:groups){cuCtxSetCurrent(g.ctx);cuEventDestroy(g.start);cuEventDestroy(g.end);cuStreamDestroy(g.stream);cuCtxSetCurrent(primary);cuGreenCtxDestroy(g.green);}cuDevicePrimaryCtxRelease(dev);}
};
